// Solitaire: Klondike patience (docs/carts/solitaire.md). Built on the card kit (the CARDS block below: decks, the
// seeded shuffle, the cards in the ROM, the stack buffers a column is composed into) and the starter's frame (title,
// pause, initials, records, saves).

// --- Colours: the default palette (DawnBringer 16). The overlay's index 0 is transparent. ---

const SHADOW = 1, PANEL = 3, RED = 6, DIM = 10, GREEN = 11, CYAN = 13, GOLD = 14, WHITE = 15;

// --- Art: made by art.py (tiles.txt, palette.txt, map.txt). The block below is rewritten each time it runs. ---

// ART (generated by art.py: do not edit)
const ART = {
  tiles: {},
  sprites: {"hand": {"pal": 1, "size": 16, "tile": 908}},
  scenes: {"table": {"h": 28, "mx": 0, "my": 0, "pal": 1, "w": 32}},
  colors: {"BACK0": 202, "BACK1": 203, "BACK2": 204, "FELTDARK": 18, "OUTLINE": 113, "PANELFILL": 115, "PANELLINE": 116},
};
// END ART

// CARDS (generated by art.py: do not edit)
const CARDS = { size: "large", back: 54, info: null, names: null, copies: null, missed: 0, loads: 0,
  sizes: { large: {"w":32,"h":48,"bytes":769,"rom":"cards_large","slots":[708,712,716,804,808,812,900,904],"parts":[[0,0,0,32],[0,32,64,16],[16,32,66,16]],"shows":[-1,-1,-1,-1,-1,-1,-1,-1],"used":[-1,-1,-1,-1,-1,-1,-1,-1]} },
  stack: {"size":"large","w":32,"h":160,"tiles":[64,68,72,76,384,388,392,396,704]} };
/** The suit of a card (0 spades, 1 hearts, 2 diamonds, 3 clubs, 4 a joker; or the custom deck's suit). */
