function cardRank(c) { return CARDS.info ? CARDS.info[c][1] : c >= 52 ? 0 : (c % 13) + 1; }
/** The rank with the ace high (14), for games where it beats the king. */
function cardHigh(c) { const r = cardRank(c); return r === 1 ? 14 : r; }
